/** Captures all log lines into the provided array for test assertions; call restoreLogger to restore the default logger. */
export function captureLogger(logLines: LogLine[]): void {
  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
    void logLines.push({level, category, message, fields});
  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
}

/** Silences all logging; call restoreLogger to restore the default logger. */
export function silenceLogger(): void {
  setLogger({debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined});
}

/** Restores default logging. */
export function restoreLogger(): void {
  setLogger();
}
